def topo_sort(graph):
    in_degree = {}
    for node in graph:
        in_degree.setdefault(node, 0)
        for prereq in graph[node]:
            in_degree.setdefault(prereq, 0)
            in_degree[prereq] += 1

    # Find all nodes that have in-degree 0 (no prerequisites)
    ready = [n for n in in_degree if in_degree[n] == 0]
    ready.sort()
    result = []

    while ready:
        node = ready.pop(0)
        result.append(node)

        # For each node that depends on `node`, reduce its in-degree
        for other in in_degree:
            if node in graph.get(other, []):
                in_degree[other] -= 1
                if in_degree[other] == 0:
                    ready.append(other)
                    ready.sort()

    if len(result) != len(in_degree):
        raise ValueError("Cycle detected")

    return result
